import { loadFont } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Audio, Easing, Img, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";

// Astral TV (cliente "Antônio plenitude", id antonio) — anúncio 9:16 para prospectar quem quer usar os estúdios, ter
// programa ou podcast, ou participar de programas com apresentadores renomados. Voz o locutor (v1, 31,5 s, entra em 0,15 s).
// Material: 1 vídeo de 54 s (1024×576, legenda queimada embaixo: os trechos em public/antonio foram cortados em cima
// da legenda), a arte da Astral TV (dela sai o recorte dos apresentadores) e o logo (círculo violeta, estrela branca e
// vermelha, fundo roxo profundo). Jeito: vitrine adaptada — filmagem horizontal em painel largo no topo, lettering
// embaixo, intercalada com cenas desenhadas (logo, apresentadores, "conhecimento transformador", chamada final).
// Referências da casa: Tauros Produções (filmagem + lettering com caixa de destaque, quadro "REC") e OmniPrime
// (cenas desenhadas, logo que vira cena, chamada final com botão do WhatsApp).

const { fontFamily: MONT } = loadFont("normal", { weights: ["500", "600", "700", "800"], subsets: ["latin", "latin-ext"] });

export const AN_FPS = 30;
export const AN_DUR = 35;
export const AN_FRAMES = AN_DUR * AN_FPS;

const BG = "#260753";
const BG2 = "#341071";
const VIOLET = "#6F2884";
const RED = "#B4152B";
const WHITE = "#FFFFFF";
const SOFT = "rgba(255,255,255,0.78)";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const io = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IN_OUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const clamp = (x: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, x));
// mola curta, com pouco overshoot
const sp = (t: number, a: number, d = 0.55) => {
  const p = clamp((t - a) / d, 0, 1);
  return p >= 1 ? 1 : 1 - Math.exp(-6 * p) * Math.cos(p * 7.5) * (1 - p * 0.2);
};

// ───────── peças ─────────
const STAR = "M0,-1 Q0.13,-0.13 1,0 Q0.13,0.13 0,1 Q-0.13,0.13 -1,0 Q-0.13,-0.13 0,-1 Z";
const Star: React.FC<{ size: number; style?: React.CSSProperties }> = ({ size, style }) => (
  <svg width={size} height={size} viewBox="-1.05 -1.05 2.1 2.1" style={{ display: "block", ...style }}>
    <path d={STAR} fill={WHITE} />
    <path d={STAR} fill={RED} transform="scale(0.6)" />
  </svg>
);
// símbolo do logo: círculo violeta com a estrela
const Symbol: React.FC<{ size: number; t?: number; at?: number; spin?: number }> = ({ size, t = 99, at = 0, spin = 0 }) => {
  const c = sp(t, at, 0.6);
  const s = sp(t, at + 0.12, 0.6);
  return (
    <div style={{ width: size, height: size, position: "relative" }}>
      <div style={{ position: "absolute", inset: 0, borderRadius: "50%", background: VIOLET, transform: `scale(${c})` }} />
      <div style={{ position: "absolute", inset: size * 0.19, transform: `scale(${s}) rotate(${(1 - s) * -90 + Math.max(0, t - at) * spin}deg)` }}>
        <Star size={size * 0.62} />
      </div>
    </div>
  );
};

// área segura dos Reels (v2, revisão da Nina): todo texto em x 170–910 e y 280–1450, com folga sobre x 120–960 / y 250–1480
const MAXW = 740;
const SAFE_TOP = 280;
const SAFE_BOTTOM = 1450;
// largura real do texto em Montserrat 800 (a fonte já está carregada quando o quadro é desenhado); só diminui se passar
const ctx = typeof document !== "undefined" ? document.createElement("canvas").getContext("2d") : null;
const fit = (txt: string, size: number, maxW = MAXW, ls = -0.01) => {
  if (!ctx) return size;
  ctx.font = `800 ${size}px "${MONT}"`;
  const wd = ctx.measureText(txt.toUpperCase()).width + ls * size * txt.length;
  return wd > maxW ? Math.floor((size * maxW) / wd) : size;
};

// texto que nasce de baixo por máscara e fica parado
const Mask: React.FC<{ t: number; at: number; children: React.ReactNode; style?: React.CSSProperties; d?: number }> = ({ t, at, children, style, d = 0.45 }) => {
  const p = k(t, at, d);
  return (
    <div style={{ overflow: "hidden", paddingBottom: "0.08em", marginBottom: "-0.08em" }}>
      <div style={{ transform: `translateY(${((1 - p) * 115).toFixed(2)}%)`, whiteSpace: "nowrap", ...style }}>{children}</div>
    </div>
  );
};
const BIG: React.CSSProperties = { fontFamily: MONT, fontWeight: 800, textTransform: "uppercase", letterSpacing: "-0.01em", lineHeight: 1.0, color: WHITE };
const SMALL: React.CSSProperties = { fontFamily: MONT, fontWeight: 600, letterSpacing: "0.005em", color: SOFT };
// palavra na caixa vermelha da estrela: a caixa abre do centro e o texto sobe dentro dela
const Hl: React.FC<{ t: number; at: number; size: number; children: string }> = ({ t, at, size: want, children }) => {
  const size = fit(children, want, MAXW - want * 0.6);
  return (
  <div style={{ position: "relative", padding: `${size * 0.14}px ${size * 0.3}px ${size * 0.1}px` }}>
    <div style={{ position: "absolute", inset: 0, background: RED, borderRadius: size * 0.12, transform: `scaleX(${k(t, at, 0.32).toFixed(4)})` }} />
    <div style={{ position: "relative" }}>
      <Mask t={t} at={at + 0.08} style={{ ...BIG, fontSize: size }}>{children}</Mask>
    </div>
  </div>
  );
};
// título grande que cabe na coluna segura
const Big: React.FC<{ t: number; at: number; size: number; txt: string; style?: React.CSSProperties }> = ({ t, at, size, txt, style }) => (
  <Mask t={t} at={at} style={{ ...BIG, ...style, fontSize: fit(txt, size, MAXW, typeof style?.letterSpacing === "string" ? parseFloat(style.letterSpacing) : -0.01) }}>{txt}</Mask>
);

type Line = { at: number; txt: string; kind: "s" | "b" | "h"; size?: number };
type Block = { a: number; b: number; lines: Line[] };
// bloco de frases: entra linha a linha; some inteiro antes do seguinte
const TextBlock: React.FC<{ t: number; blk: Block; gap?: number }> = ({ t, blk, gap = 10 }) => {
  if (t < blk.a - 0.05 || t >= blk.b) return null;
  const o = 1 - lin(t, blk.b - 0.12, blk.b);
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap, opacity: o }}>
      {blk.lines.map((l, i) =>
        l.kind === "s" ? (
          <Mask key={i} t={t} at={l.at} style={{ ...SMALL, fontSize: l.size ?? 50 }}>{l.txt}</Mask>
        ) : l.kind === "b" ? (
          <Big key={i} t={t} at={l.at} size={l.size ?? 112} txt={l.txt} />
        ) : (
          <div key={i} style={{ marginTop: 8 }}><Hl t={t} at={l.at} size={l.size ?? 100}>{l.txt}</Hl></div>
        ),
      )}
    </div>
  );
};
// bloco centrado verticalmente num trecho do quadro (mede pelo flex, sem conta de altura)
const Center: React.FC<{ top: number; bottom: number; children: React.ReactNode }> = ({ top, bottom, children }) => (
  <div style={{ position: "absolute", left: 120, right: 120, top, height: bottom - top, display: "flex", alignItems: "center", justifyContent: "center" }}>
    <div style={{ position: "relative", width: "100%" }}>{children}</div>
  </div>
);
const TextZone: React.FC<{ t: number; blocks: Block[] }> = ({ t, blocks }) => (
  <>
    {blocks.map((blk, i) =>
      t >= blk.a - 0.05 && t < blk.b ? (
        <Center key={i} top={TXT_TOP} bottom={TXT_BOTTOM}>
          <TextBlock t={t} blk={blk} />
        </Center>
      ) : null,
    )}
  </>
);

// ───────── filmagem num cartão embaixo, dentro da área segura; marca e lettering em cima ─────────
const CX = 170;
const CY = 830;
const CW = 740;
const PH = 620; // altura do cartão
const BRAND_TOP = 286;
const TXT_TOP = 360;
const TXT_BOTTOM = CY - 20;
const SRC_W = 2048;
const SRC_H = 920;
type Tr = "cut" | "flash" | "push" | "wipe" | "iris";
type Shot = { c: string; a: number; b: number; fx: number; from?: number; rate?: number; tr?: Tr };
const ShotView: React.FC<{ s: Shot; t: number }> = ({ s, t }) => {
  const lt = t - s.a;
  const z = 1.0 + 0.06 * lin(t, s.a, s.b + 0.4) + (s.tr === "flash" ? 0.12 * (1 - k(t, s.a, 0.45)) : 0);
  const sc = (PH / SRC_H) * z;
  const W = SRC_W * sc;
  const H = SRC_H * sc;
  const left = clamp(CW / 2 - s.fx * W, CW - W, 0);
  let clip: string | undefined;
  let tx = 0;
  if (s.tr === "push") tx = (1 - k(t, s.a, 0.38)) * CW;
  if (s.tr === "wipe") clip = `inset(0 0 0 ${((1 - io(t, s.a, 0.4)) * 100).toFixed(2)}%)`;
  if (s.tr === "iris") clip = `circle(${(io(t, s.a, 0.45) * 75).toFixed(2)}% at 50% 50%)`;
  return (
    <div style={{ position: "absolute", left: 0, top: 0, width: CW, height: PH, overflow: "hidden", transform: `translateX(${tx}px)`, clipPath: clip }}>
      <Sequence from={Math.round(s.a * AN_FPS)} durationInFrames={Math.round((s.b - s.a + 0.5) * AN_FPS)} layout="none">
        <OffthreadVideo
          src={staticFile(`antonio/${s.c}.mp4`)}
          muted
          startFrom={Math.round((s.from ?? 0) * AN_FPS)}
          playbackRate={s.rate ?? 1}
          style={{ position: "absolute", width: W, height: H, left, top: (PH - H) / 2 }}
        />
      </Sequence>
      {s.tr === "wipe" && lt < 0.45 ? (
        <div style={{ position: "absolute", top: 0, bottom: 0, width: 26, left: `${((1 - io(t, s.a, 0.4)) * 100).toFixed(2)}%`, marginLeft: -13, background: RED }} />
      ) : null}
    </div>
  );
};
// quadro de câmera: cantos, REC e contador
const Viewfinder: React.FC<{ t: number }> = ({ t }) => {
  const m = 26;
  const L = 54;
  const corner = (x: number, y: number, sx: number, sy: number) => (
    <div style={{ position: "absolute", left: x, top: y, width: L, height: L, borderLeft: sx > 0 ? "5px solid rgba(255,255,255,0.9)" : undefined, borderRight: sx < 0 ? "5px solid rgba(255,255,255,0.9)" : undefined, borderTop: sy > 0 ? "5px solid rgba(255,255,255,0.9)" : undefined, borderBottom: sy < 0 ? "5px solid rgba(255,255,255,0.9)" : undefined }} />
  );
  const fr = Math.floor(t * AN_FPS);
  const tc = `00:00:${String(Math.floor(t)).padStart(2, "0")}:${String(fr % AN_FPS).padStart(2, "0")}`;
  return (
    <>
      {corner(m, m, 1, 1)}
      {corner(CW - m - L, m, -1, 1)}
      {corner(m, PH - m - L, 1, -1)}
      {corner(CW - m - L, PH - m - L, -1, -1)}
      <div style={{ position: "absolute", left: m + 26, top: m + 20, display: "flex", alignItems: "center", gap: 12, fontFamily: MONT, fontWeight: 700, fontSize: 26, color: WHITE, letterSpacing: "0.06em", textShadow: "0 2px 8px rgba(0,0,0,0.5)" }}>
        <div style={{ width: 18, height: 18, borderRadius: "50%", background: "#FF2D3D", opacity: Math.floor(t * 2) % 2 === 0 ? 1 : 0.35 }} />
        REC
      </div>
      <div style={{ position: "absolute", right: m + 26, top: m + 22, fontFamily: MONT, fontWeight: 600, fontSize: 24, color: WHITE, fontVariantNumeric: "tabular-nums", letterSpacing: "0.04em", textShadow: "0 2px 8px rgba(0,0,0,0.5)" }}>{tc}</div>
    </>
  );
};
const Footer: React.FC = () => (
  <div style={{ position: "absolute", left: 0, right: 0, top: BRAND_TOP, display: "flex", justifyContent: "center", alignItems: "center", gap: 16 }}>
    <Symbol size={56} />
    <div style={{ fontFamily: MONT, fontWeight: 800, fontSize: 36, color: WHITE, letterSpacing: "0.02em" }}>ASTRAL TV</div>
  </div>
);
const Flash: React.FC<{ t: number; at: number; o?: number }> = ({ t, at, o = 0.45 }) =>
  t >= at && t < at + 0.14 ? <div style={{ position: "absolute", left: 0, top: 0, width: CW, height: PH, background: WHITE, opacity: o * (1 - (t - at) / 0.14) }} /> : null;

// fundo das cenas desenhadas: roxo liso com uma luz larga e parada no centro
const Plain: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ background: `radial-gradient(90% 60% at ${50 + Math.sin(t * 0.6) * 12}% ${45 + Math.cos(t * 0.45) * 6}%, ${BG2} 0%, ${BG} 70%)` }} />
);

const FootScene: React.FC<{ t: number; shots: Shot[]; blocks: Block[] }> = ({ t, shots, blocks }) => (
  <AbsoluteFill style={{ background: BG }}>
    <Plain t={t} />
    <Footer />
    <TextZone t={t} blocks={blocks} />
    <div style={{ position: "absolute", left: CX, top: CY, width: CW, height: PH, overflow: "hidden", borderRadius: 30, background: "#000", boxShadow: "0 36px 80px rgba(8,0,28,0.55)" }}>
      {shots.map((s, i) => (t >= s.a - 0.02 && t < s.b + 0.45 ? <ShotView key={i} s={s} t={t} /> : null))}
      {shots.map((s, i) => (s.tr === "flash" ? <Flash key={i} t={t} at={s.a} /> : null))}
      <Viewfinder t={t} />
    </div>
  </AbsoluteFill>
);

// ───────── cenas ─────────
const V = 0.15; // a voz entra em 0,15 s
const w = (x: number) => x + V;

// 1 · gancho e podcast (0–6,45)
const F1_SHOTS: Shot[] = [
  { c: "e", a: 0, b: 0.2, fx: 0.27 },
  { c: "m", a: 0.2, b: 0.4, fx: 0.45, tr: "cut" },
  { c: "h", a: 0.4, b: 0.6, fx: 0.5, from: 2, tr: "cut" },
  { c: "a", a: 0.6, b: 3.05, fx: 0.7, rate: 0.88, tr: "flash" },
  { c: "j", a: 3.05, b: 4.95, fx: 0.5, rate: 0.72, tr: "wipe" },
  { c: "h", a: 4.95, b: 6.45, fx: 0.5, tr: "push" },
];
const F1_TXT: Block[] = [
  { a: 0.15, b: 2.95, lines: [{ at: 0.2, txt: "já pensou em ter o", kind: "s" }, { at: w(0.72), txt: "seu próprio", kind: "b" }, { at: w(1.26), txt: "programa", kind: "b" }, { at: w(1.69), txt: "de TV?", kind: "h" }] },
  { a: 3.05, b: 4.25, lines: [{ at: 3.07, txt: "ou o seu", kind: "s" }, { at: w(3.04), txt: "podcast", kind: "h", size: 120 }] },
  { a: 4.29, b: 6.45, lines: [{ at: 4.29, txt: "gravado num", kind: "s" }, { at: w(4.72), txt: "estúdio", kind: "b", size: 124 }, { at: w(5.11), txt: "de verdade", kind: "h" }] },
];

// 2 · a Astral TV abre os estúdios (6,45–9,75)
const D1: React.FC<{ t: number }> = ({ t }) => {
  const a = 6.45;
  const cam = 1 + 0.05 * lin(t, a, 9.9);
  return (
    <AbsoluteFill>
      <Plain t={t} />
      <AbsoluteFill style={{ transform: `scale(${cam})` }}>
        <Center top={SAFE_TOP} bottom={SAFE_BOTTOM}>
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
            <Symbol size={440} t={t} at={a} spin={9} />
            <div style={{ height: 56 }} />
            <Big t={t} at={a + 0.22} size={140} txt="Astral TV" style={{ letterSpacing: "0.01em" }} />
            <div style={{ height: 110 }} />
            <Mask t={t} at={w(6.87)} style={{ ...SMALL, fontSize: 60 }}>abre os estúdios</Mask>
            <div style={{ height: 22 }} />
            <Hl t={t} at={w(7.98)} size={116}>pra você</Hl>
          </div>
        </Center>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// 3 · crie, grave ou participe (9,75–17,0)
const F2_SHOTS: Shot[] = [
  { c: "e", a: 9.75, b: 11.0, fx: 0.27 },
  { c: "l", a: 11.0, b: 12.55, fx: 0.72, tr: "push" },
