];
const F2_TXT: Block[] = [
  { a: 9.8, b: 10.95, lines: [{ at: 9.8, txt: "crie o seu", kind: "s" }, { at: w(10.03), txt: "programa", kind: "h", size: 112 }] },
  { a: 11.0, b: 12.45, lines: [{ at: 11.0, txt: "grave o seu", kind: "s" }, { at: w(11.68), txt: "podcast", kind: "h", size: 120 }] },
  { a: 12.49, b: 14.05, lines: [{ at: 12.49, txt: "ou participe de", kind: "s" }, { at: w(13.18), txt: "programas", kind: "b", size: 120 }] },
  { a: 14.1, b: 15.9, lines: [{ at: 14.1, txt: "com apresentadores", kind: "s" }, { at: w(14.8), txt: "renomados", kind: "h", size: 108 }] },
