];

// 4 · Leão Lobo e Claudete Troiano (17,0–19,45): o recorte da arte deles num cartão
const D2: React.FC<{ t: number }> = ({ t }) => {
  const a = 17.0;
  const card = sp(t, a + 0.05, 0.6);
  return (
    <AbsoluteFill>
      <Plain t={t} />
      <Center top={SAFE_TOP} bottom={SAFE_BOTTOM}>
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 22 }}>
          <div style={{ width: 860, height: 677, borderRadius: 38, overflow: "hidden", position: "relative", boxShadow: "0 40px 90px rgba(10,0,30,0.55)", transform: `translateY(${(1 - card) * 260}px) scale(${0.9 + 0.1 * card})`, opacity: lin(t, a, a + 0.15) }}>
            <Img src={staticFile("antonio/apresentadores.jpg")} style={{ position: "absolute", width: 860, height: 677, transform: `scale(${1.02 + 0.05 * lin(t, a, 19.5)})`, transformOrigin: "50% 40%" }} />
          </div>
          <div style={{ height: 40 }} />
          <Hl t={t} at={a + 0.12} size={84}>Leão Lobo</Hl>
          <Mask t={t} at={w(17.4)} style={{ ...SMALL, fontSize: 46 }}>e</Mask>
          <Hl t={t} at={w(17.54)} size={66}>Claudete Troiano</Hl>
        </div>
      </Center>
