// ───────── passagens entre cenas (cada uma diferente) ─────────
const STAR_Y = 650; // centro da estrela da cena 6
type Layer = { a: number; b: number; enter: (t: number) => React.CSSProperties; el: (t: number) => React.ReactNode };
const circleIn = (a: number, x: string, y: string, d = 0.45) => (t: number): React.CSSProperties => ({ clipPath: `circle(${(io(t, a, d) * 150).toFixed(2)}% at ${x} ${y})` });
const LAYERS: Layer[] = [
  { a: 0, b: 6.45, enter: () => ({}), el: (t) => <FootScene t={t} shots={F1_SHOTS} blocks={F1_TXT} /> },
  // a cor roxa sobe do lettering e cobre a tela
  { a: 6.45, b: 9.75, enter: circleIn(6.45, "50%", "30%"), el: (t) => <D1 t={t} /> },
  // o círculo do logo vira a janela da filmagem
  { a: 9.75, b: 17.0, enter: circleIn(9.75, "50%", "31%", 0.5), el: (t) => <FootScene t={t} shots={F2_SHOTS} blocks={F2_TXT} /> },
  // a cena dos apresentadores sobe de baixo, com borda vermelha
  { a: 17.0, b: 19.45, enter: (t) => ({ clipPath: `inset(${((1 - io(t, 17.0, 0.42)) * 100).toFixed(2)}% 0 0 0)` }), el: (t) => <D2 t={t} /> },
  { a: 19.45, b: 23.0, enter: (t) => ({ transform: `translateX(${((1 - k(t, 19.45, 0.42)) * 1080).toFixed(1)}px)` }), el: (t) => <FootScene t={t} shots={F3_SHOTS} blocks={F3_TXT} /> },
  { a: 23.0, b: 26.45, enter: circleIn(23.0, "50%", "60%"), el: (t) => <D3 t={t} /> },
  // a estrela cresce e vira a janela da filmagem
  {
    a: 26.45,
    b: 28.75,
    enter: (t) => {
      const p = io(t, 26.45, 0.45);
      if (p >= 1) return {};
      // estrela de 4 pontas com lados côncavos (a do logo), em px, centrada onde estava a estrela da cena anterior
      const s = 10 + p * 3400;
      const pts: string[] = [];
      for (let i = 0; i < 96; i++) {
        const ang = (i / 96) * Math.PI * 2;
        const c = Math.abs(Math.cos(ang));
        const sn = Math.abs(Math.sin(ang));
        const r = 1 / Math.pow(Math.pow(c, 0.55) + Math.pow(sn, 0.55), 1 / 0.55);
        pts.push(`${(540 + Math.cos(ang) * r * s).toFixed(1)}px ${(STAR_Y + Math.sin(ang) * r * s).toFixed(1)}px`);
      }
      return { clipPath: `polygon(${pts.join(",")})` };
    },
    el: (t) => <FootScene t={t} shots={F4_SHOTS} blocks={F4_TXT} />,
  },
  { a: 28.75, b: 35.1, enter: (t) => ({ transform: `translateY(${((1 - k(t, 28.75, 0.45)) * 1920).toFixed(1)}px)` }), el: (t) => <D4 t={t} /> },
];

export const Antonio: React.FC<{ som?: boolean }> = ({ som = true }) => {
  const t = useCurrentFrame() / AN_FPS;
  return (
    <AbsoluteFill style={{ background: BG }}>
      {LAYERS.map((L, i) => {
        const next = LAYERS[i + 1];
        const until = next ? next.a + 0.55 : L.b;
        if (t < L.a - 0.01 || t >= until) return null;
        return (
          <AbsoluteFill key={i} style={L.enter(t)}>
            {L.el(t)}
          </AbsoluteFill>
        );
      })}
      {som ? <Audio src={staticFile("antonio/antonio-mix.wav")} /> : null}
    </AbsoluteFill>
  );
};

